mapper.select:
select * from ( select o.id, g.id glue_group_id, g.glue_group_code, g.glue_group_name, o.glue_code, o.order_num, g.order_num||'.'||o.order_num as glue_group_order_num, o.remark from T_TM_GLUE_GROUP_ORDER g inner join T_TM_GLUE_ORDER o on g.id = o.glue_group_id where 1=1 and g.del_flag=0 and o.del_flag=0
and GLUE_GROUP_ID = #{glueGroupId}
and INSTR(GLUE_CODE, #{glueCode}) > 0
order by g.order_num, o.order_num
) t
order by ${orderStr}

mapper.update:
merge into T_TM_GLUE_ORDER a USING (
select #{GlueOrder.glueGroupId,jdbcType=DOUBLE} GLUE_GROUP_ID, #{GlueOrder.glueCode,jdbcType=VARCHAR} GLUE_CODE, #{GlueOrder.orderNum,jdbcType=DOUBLE} ORDER_NUM, #{GlueOrder.createBy,jdbcType=VARCHAR} create_by, #{GlueOrder.createTime,jdbcType=DATE} create_time, #{GlueOrder.updateBy,jdbcType=VARCHAR} update_by, #{GlueOrder.updateTime,jdbcType=DATE} update_time, #{GlueOrder.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.GLUE_CODE = b.GLUE_CODE AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.GLUE_GROUP_ID = b.GLUE_GROUP_ID, a.ORDER_NUM = b.ORDER_NUM, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.GLUE_GROUP_ID , a.GLUE_CODE , a.ORDER_NUM , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_PUBLIC.NEXTVAL, b.GLUE_GROUP_ID, b.GLUE_CODE, b.ORDER_NUM, b.create_by, sysdate, b.remark, '0' )
